def val(label,expr,key,kp,direct,method,components=None):
 p=v(label,expr,key,kp,method);p.update(assessed_8227_demand_ids=direct,component_demand_ids=components or[],given_representation='graph',response_format='symbolic');return p
def area(label,segments,key,kp,method):
 expr='+'.join(f'({sign})*integrate({f},(x,{lo},{hi}))'for f,lo,hi,sign in segments)
 p=val(label,expr,key,kp,[AREA],method,[DEF,INT])
 p.update(response_format='numeric',units='units^2',printed_key_units='units^2',original_area_segments=[dict(integrand=f,lower=str(lo),upper=str(hi),area_multiplier=sign)for f,lo,hi,sign in segments])
 for j,(f,lo,hi,sign)in enumerate(segments):p.setdefault('additional_operations',{})[f'proper-component-{j+1}']={'kind':'proper-definite-integral','operands':[f,str(lo),str(hi)]}
 return p
def add(kind,n,page,note,parts,powers,rep='graph'):
 direct=sorted({d for p in parts for d in p.get('assessed_8227_demand_ids',[])})
 comp=sorted({d for p in parts for d in p.get('component_demand_ids',[])}-set(direct))
 r=h.add(kind,n,page,note,parts,direct,comp,powers=powers)
 r.update(representation=rep,mapping_rationale='Requested intersections/tangent or normal data/area are separate direct outputs. An intermediate construction is a component when it is not independently requested. Read the actual shaded boundary:the desired region may lie under BOTH curves with an axis boundary,rather than BETWEEN them. Reject algebraic roots violating source branches or plotted bounds.')
 for p in parts:p['given_representation']=rep
 return r
